def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    value = new - old
    return {
        "value": value,
        "trace": {
            "old_2018_net_income_loss": old,
            "new_2019_net_income_loss": new,
            "change": value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
